    Write-Output "===== $r ====="
    try { $j = Get-Content $p -Raw | ConvertFrom-Json; $j.scripts.PSObject.Properties | ForEach-Object { "  $($_.Name): $($_.Value)" } } catch { Write-Output "  (parse fail)" }
